"""Write current evidence with a plain-language interpretation."""
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
from .full_readout_fit import HERE
from .cap_controlled_core import shape_metrics

def run(out):
    d=json.loads((out/'run.json').read_text());profiles=json.loads((out/'profiles.json').read_text());prior=Path(d['parent']);base=np.array(d['baseline']);baseline=json.loads((prior/'score_selected.json').read_text());q=pd.read_csv(prior/'prices_canonical_selected.csv');bshape=json.loads((out/'baseline_replay.json').read_text())['shape'];selection=d['selection'];fresh=out/'fresh_check';fb=json.loads((fresh/'score_baseline.json').read_text());lines=[]
    def add(s=''):lines.append(s)
    vf=lambda r:r['original_otm_components']['VIX']+r['original_otm_components']['forwards']
    cv=lambda r:r['canonical_components']['VIX']+r['canonical_components']['forwards']
    add('# Controlled cap comparison: a cleaner experiment');add();add('25 October 2026. Completed bounded investigation. The selected baseline and every historical run remain unchanged. New evidence is in `runs/m2_cap_controlled_001`; all agreed maturities and 4096 paths per strike are retained. These are experimental comparisons, not adopted joint calibrations.');add()
    add('## In everyday terms');add();add('We eased the brake on extreme volatility while stopping the fit from changing unrelated parts of the expected-variance curve. This makes the comparison much easier to interpret than the previous VIX-only fit. The experiment separates whether the brake can help from the damage caused by moving variance at times that VIX options do not observe.');add()
    add('The model still rescales volatility by its own average multiplier. Consequently a gentler brake redistributes variance between ordinary and extreme states; it does not simply increase every option price. We kept that rescaling in every candidate.');add()
    add('## Exactly what changed');add();add('The variance floor stays at .00264 (5.138% instantaneous volatility), with positive beta_J unchanged. All original score coefficients, OU rates/geometric grids, initial state, correlations and Q risk-price scenario are fixed. SPX 29/57/119/211/302/666/1030 days, VIX 27/55/118/153 days, all four forwards and 1511 original OTM targets remain. Market puts use market-forward parity; native model puts use model forwards. No jumps, quintic proposal, smoothing or price clipping.');add()
    add('Only four broad adjustments can move expected variance: one over each VIX window [27,57], [55,85], [118,148], [153,183] days. Where the first two windows overlap, their adjustments are averaged. With B the normalized window-indicator matrix and s the four adjustments:');add();add('    xi_new = xi_baseline + (xi_baseline - floor) * (B @ s), |s_j| <= 0.15.');add();add('This keeps every off-window curve piece exactly fixed and changes excess variance by at most 15% per piece. xi remains above the floor, with no monotonicity condition. All boundaries already exist in the 16-piece curve. The 15% range is a declared experimental choice, not a user requirement.');add()
    add('Nine shapes cross cap-level increases 0/.375/.75 with continuation strengths a=0/.25/.5. Sharpness remains 2. At a=0 the model retains the logistic cap. At a>0 it adds a*log(1+softplus(k*(eta-L))/k) to the tempered score, permitting slow growth beyond the transition. Since a<=.5, the controlled-growth moment and stock-martingality arguments in [CAP_TAIL_MATHEMATICS.md](CAP_TAIL_MATHEMATICS.md) continue to apply under their stated assumptions.');add()
    add('Each shape fits only the four window adjustments using native VIX price-plus-forward loss. Diagnostic screens require forwards within .5 point of market and common-call VIX-plus-forward loss no worse than the unchanged baseline. Those screens are implementation choices. All nine local fits terminate successfully, but this finite grid and local optimization are not a global convergence result.');add()
    add('## All nine training outcomes');add();add('|Shape|Cap-level increase|Continuation a|Native VIX + forward loss|Right-wing IV MAE|Near-ATM IV MAE|Preferred screen|');add('|---|---:|---:|---:|---:|---:|:---:|');add(f"|Unchanged baseline|0|0|{vf(baseline):.6f}|{bshape['wing_MAE']:.3f}|{bshape['ATM_MAE']:.3f}|reference|")
    for r in profiles:add(f"|{r['name']}|{r['cap_shift']:g}|{r['continuation']:g}|{r['fit']['native_loss']:.6f}|{r['shape']['wing_MAE']:.3f}|{r['shape']['ATM_MAE']:.3f}|{'yes' if r['preferred'] else 'no'}|")
    add();add('IV MAE means average absolute implied-volatility error in percentage points, giving each maturity equal weight. Right wing uses K/F>2; near ATM uses |log(K/F)|<=.2. These summarize raw implied volatilities; they do not smooth prices. A preferred candidate must improve native loss, keep all wing IVs available, and worsen near-ATM IV MAE by no more than 5 points. Feasible candidates are ranked by wing MAE within the capped and continued families separately. This selects a useful shape comparison rather than merely the smallest aggregate loss.');add()
    add('Both representatives were frozen using TRAINING results before any new checking states were generated:');add()
    for row in selection:
        r=next(z for z in profiles if z['name']==row['name']);s=np.array(r['fit']['adjustments']);add(f"- **{row['name']} ({row['family']})**: L increases by {r['cap_shift']:g}, a={r['continuation']:g}; four excess-variance adjustments are {', '.join(f'{100*x:+.3f}%' for x in s)}. Floor/off-window levels are exactly unchanged.")
    add();add('All nine fits reach the common-call loss safeguard, approximately 45.509602. Several also reach the +.5-point forward-error boundary at 118/153 days. Therefore this experiment does not show that the cap families have exhausted their flexibility: the chosen fitting safeguards are active. Larger cap/continuation changes improve wing errors further, but their fitted native price losses and near-ATM errors worsen in this comparison.');add()
    add('## Actual SPX tradeoffs and genuinely fresh VIX checking');add();add('|Candidate|Training SPX loss|Training native VIX + forwards|Training native joint loss|NEW-stream VIX + forwards|');add('|---|---:|---:|---:|---:|');add(f"|Unchanged baseline|{baseline['original_otm_components']['SPX']:.6f}|{vf(baseline):.6f}|{baseline['original_otm_loss']:.6f}|{vf(fb):.6f}|")
    scores=[]
    for row in selection:
        n=row['name'];s=json.loads((out/'full'/f'score_{n}.json').read_text());fc=json.loads((fresh/f'score_{n}.json').read_text());scores.append((row,s,fc));add(f"|{n}|{s['original_otm_components']['SPX']:.6f}|{vf(s):.6f}|{s['original_otm_loss']:.6f}|{vf(fc):.6f}|")
    add();add('Every SPX value above comes from full nonlinear repricing at all seven dates, recomputing volatility and stock along all 4096 cached OU/equity paths per expiry. Only primitives and valid frozen controls are reused. No terminal stock path was treated as unchanged after a model change.');add()
    for row,s,fc in scores:
        n=row['name'];p=json.loads((out/'full'/f'paired_{n}.json').read_text());fp=json.loads((fresh/f'paired_{n}.json').read_text());cs=[s['canonical_loss']<baseline['canonical_loss'],s['original_otm_loss']<baseline['original_otm_loss'],cv(s)<cv(baseline)-1e-8,vf(s)<vf(baseline)-1e-8];add(f"- {n}: training SPX loss change {p['change'][1]:+.6f}, descriptive paired eight-block jackknife SE {p['jackknife_SE'][1]:.6f}; native joint change {p['change'][0]:+.6f}, SE {p['jackknife_SE'][0]:.6f}. New-stream native VIX-plus-forward change {fp['change'][2]:+.6f}, paired eight-net SE {fp['jackknife_SE'][2]:.6f}. Strict sampled decreases in all four prior joint/VIX conventions: {all(cs)}. The common-call VIX guard is effectively at equality, so tiny roundoff differences are not meaningful improvement.")
    add();add('|Candidate|Native prices inside bid/ask /1511|Negative native prices|Unavailable common-call IVs|SPX monotonicity / convexity flags|');add('|---|---:|---:|---:|---:|')
    for name,ss in [('baseline',baseline)]+[(row['name'],ss) for row,ss,_ in scores]:
        sp=[z for z in ss['shapes'] if z['instrument']=='SPX'];add(f"|{name}|{ss['inside_original_otm_bidask']}|{ss['native_otm_negative_prices']}|{ss['iv_unavailable']}|{sum(z['monotonicity_violations'] for z in sp)} / {sum(z['convexity_violations'] for z in sp)}|")
    add();add('Shape flags concern finite controlled price estimates, not proven model-level arbitrage. The same fixed control functions can introduce finite-sample convexity artifacts; no plotted smoothing or replacement hides them.')
    add();add('The new-stream aggregate VIX gains are smaller than one reported paired jackknife SE. They do not establish a precise improvement in expected aggregate price loss, even though the wing curves visibly move closer to market. SPX loss deterioration persists across all eight leave-one-block comparisons for both candidates. These losses are fitting-error scores; a doubled score does not mean option prices doubled.')
    add();add('This supplies the actual tradeoff after removing the previous off-window/floor confounding. It remains a controlled combination of cap changes and the four small window adjustments, not a pure cap-only intervention. The earlier fixed-curve cap profiles provide that complementary comparison.');add()
    add('The checking experiment uses eight newly generated 512-point scrambled nets per VIX maturity, the unchanged defensive-mixture proposal and exact p/q weights, with no weight self-normalization. Training-pilot control coefficients remain frozen. Selection precedes new draw generation; checking results do not trigger reselection. Seeds are regenerated and checked against recorded historical production/pilot/diagnostic seeds. New random streams check numerical stability on the SAME in-sample market quotes; they are not market out-of-sample observations. SPX comparisons use the original training cache; no fresh SPX ensemble was run.');add()
    add('## Smile shape by maturity');add();add('|Candidate|Days|Wing IV MAE|Wing slope|Wing curvature|Near-ATM IV MAE|Unavailable IVs|');add('|---|---:|---:|---:|---:|---:|---:|')
    shape_rows=[]
    for name,quotes in [('baseline',q[q.instrument.eq('VIX')].reset_index(drop=True))]+[(row['name'],pd.read_csv(out/f"prices_canonical_{row['name']}.csv")) for row in selection]:
        m=shape_metrics(quotes,quotes.model_price_U.to_numpy())
        for v in m['rows']:
            shape_rows.append(dict(candidate=name,**v));add(f"|{name}|{v['days']}|{v['wing_MAE']:.3f}|{v['wing_slope']:.3f}|{v['wing_curvature']:.3f}|{v['ATM_MAE']:.3f}|{v['unavailable']}|")
    pd.DataFrame(shape_rows).to_csv(out/'selected_smile_shape.csv',index=False);add();add('Slope and curvature are descriptive linear/quadratic regressions of raw IV against log strike within the right-wing region; they are not an asymptotic theorem or a new polynomial volatility model. Complete quote prices and pointwise SE remain saved. A steeper wing and a lower average price loss do not imply that every maturity or strike improved.');add()
    add('Fresh-stream equal-maturity IV error summaries:');add();add('|Candidate|New-stream wing IV MAE|New-stream near-ATM IV MAE|');add('|---|---:|---:|')
    fresh_shapes=[]
    for name in ['baseline']+[z['name'] for z in selection]:
        fq=pd.read_csv(fresh/f'prices_canonical_{name}.csv');m=shape_metrics(fq,fq.model_price_U.to_numpy());fresh_shapes.append(dict(candidate=name,**m));add(f"|{name}|{m['wing_MAE']:.3f}|{m['ATM_MAE']:.3f}|")
    (out/'fresh_smile_shape.json').write_text(json.dumps(fresh_shapes,indent=2)+'\n');add()
    add('## Weighted tails and second moments on new streams');add();mom=pd.read_csv(fresh/'moments.csv');add('|Candidate|Days|E[VIX²] estimate|Curve-implied target|Eight-net SE|Difference / SE|');add('|---|---:|---:|---:|---:|---:|')
    for v in mom.itertuples():add(f'|{v.candidate}|{v.days}|{v.second:.4f}|{v.target:.4f}|{v.second_SE:.4f}|{(v.second-v.target)/v.second_SE:+.2f}|')
    rr=mom[(mom.candidate=='baseline')&mom.days.eq(153)].iloc[0];add();add(f"On the new baseline draws, day 153 gives {rr.second:.3f} versus {rr.target:.3f}, SE {rr.second_SE:.3f}, about {(rr.target-rr.second)/rr.second_SE:.2f} SE below target. That is closer than the historical reused-check estimate 606.208 versus 610.933 (SE 1.635), consistent with outer-draw sensitivity. One new eight-net ensemble is not a convergence pass.")
    add();add('The second-moment target changes only with each candidate’s four allowed curve adjustments. A new estimate closer to its target would not erase the historical 153-day discrepancy or certify convergence. Eight nets give limited information about rare tails and normalizer/conditional/time/stock errors remain separate.');add()
    tail=pd.read_csv(fresh/'tails.csv');add('|Candidate|Days|Highest strike|Proposal hits|Weighted probability|Raw call ± SE|Payoff ESS|Top10 share|');add('|---|---:|---:|---:|---:|---:|---:|---:|')
    for (name,day),g in tail.groupby(['candidate','days'],sort=False):
        v=g.loc[g.strike.idxmax()];add(f'|{name}|{day}|{v.strike:g}|{int(v.hits)}|{v.probability:.5g}|{v.raw_call:.6g} ± {v.call_SE:.2g}|{v.payoff_ESS:.1f}|{100*v.top10_share:.1f}%|')
    add();add('These raw prices use likelihood-weighted payoff contributions. Actual controlled option prices also contain signed zero-mean control corrections. Raw hit counts alone do not establish sufficient risk-neutral tail mass. The table and plots expose payoff concentration and uncertainty without clipping or self-normalizing weights.');add()
    add('## Verification and limits');add()
    audit=json.loads((out/'audit.json').read_text());add(f"- Three standard-library tests check exact frozen coordinates, all adjustment-domain corners, overlap behavior, baseline nesting and basis derivatives. Production VIX objective sensitivities are checked for all nine shapes.")
    add(f"- Independent audit passes {audit['saved_score_records']} saved score records, {audit['four_window_fit_trials_replayed']} fit-trial objective/forward reconstructions from archived exposures, {audit['frozen_source_checks']} source snapshot hashes and all {audit['exact_fresh_scramble_replays']} complete new scramble/state/likelihood regenerations. It confirms the parent selection is unchanged.")
    add(f"- Representative direct same-GH32 conditional checks on new extreme states have maximum interpolation relative error {max(z['relative_error'] for z in audit['direct_conditional_GH32_checks']):.3g}. This checks the fast integration table against that finite quadrature rule, not continuous-price convergence.")
    add('- GH32 conditional, GH48 normalization, time order 8 and the cached stock512 mesh remain approximations. Earlier representative order refinements are historical evidence, not a fresh whole-surface certificate for every candidate. Finite SE omits unsampled tails, deterministic bias, pilot and parameter uncertainty.')
    add('- Finite Gaussian moments of the multiplier and a true stock martingale establish different properties. They do not by themselves prove a finite second moment for long-maturity stock option payoffs or for importance-weighted estimators. The log-continuation candidate has no new population payoff-variance certificate; reported block/net SEs are descriptive numerical evidence.')
    add('- Signed prices, unavailable IVs, raw forward-ratio and shape flags remain in saved CSV/JSON/NPZ files. No new Lean/P-compatibility, global optimum or accepted production-fit claim is made.');add()
    add('The first attempt stopped before fresh model pricing because the engine constructor expected stock-cache metadata in the VIX-only directory. The setup was corrected; both fits, both completed SPX evaluations and all 32 saved fresh scrambles were retained. Only fresh VIX pricing resumed. The original failure log/source snapshots and separately captured correction/continuation are preserved; no random streams or candidate selections were replaced.');add()
    add('## Decision and how to read the result');add()
    if all(ss['original_otm_components']['SPX']>baseline['original_otm_components']['SPX'] for _,ss,_ in scores):
        add('Both tested representatives improve right-wing VIX shape but worsen the actual training SPX loss. Preserve the selected baseline. These candidates do not supply the desired joint improvement, even after unrelated curve changes are removed. The earlier catastrophic SPX losses were confounded by excessive curve freedom; the remaining tradeoff here is a more interpretable cap-plus-small-window-adjustment effect.')
    else:
        add('Compare actual cross-market tradeoffs and their paired uncertainty before any adoption; the selected baseline is preserved.')
    add();add('The result is not a proof that every cap modification fails. All nine fits hit an active common-call safeguard; stronger tail freedom reduces wing IV errors further but worsens the tested price/ATM compromise. Separate changing the model from changing the fitting requirements. A next mechanism experiment can target stochastic response strength, with persistence independently controlled by a dedicated continuous state, while retaining this clean four-window/fixed-floor design. That additional layer remains a separately specified proposal; it was not implemented or calibrated in this run.');add()
    add('Plots and reading guide: [cap-controlled015](visualizations/cap-controlled015/README.md). Plan: [CAP_CONTROLLED_PLAN.md](CAP_CONTROLLED_PLAN.md). Run: `runs/m2_cap_controlled_001`. Reproduce with modules `cap_controlled_study --output NEW_DIRECTORY` (current driver includes the VIX-only setup correction), `audit_cap_controlled --run RUN`, `plot_cap_controlled --run RUN --output PLOTS`, and `summarize_cap_controlled --run RUN` using the existing pdv-options-venv environment and package PYTHONPATH.');add()
    (HERE/'CAP_CONTROLLED_RESULTS.md').write_text('\n'.join(lines)+'\n');print('Wrote CAP_CONTROLLED_RESULTS.md')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);run(p.parse_args().run.resolve())
